<?php
require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_csrf();oecrm_require_permission($conn,'backups','create');$dir=__DIR__.'/../storage/backups';if(!is_dir($dir))mkdir($dir,0700,true);$name='oecrm_'.date('Ymd_His').'.sql';$path=$dir.'/'.$name;$tables=[];$q=mysqli_query($conn,'SHOW TABLES');while($r=mysqli_fetch_row($q))$tables[]=$r[0];$sql="SET FOREIGN_KEY_CHECKS=0;\n";foreach($tables as $table){$create=mysqli_fetch_row(mysqli_query($conn,'SHOW CREATE TABLE `'.$table.'`'));$sql.="\nDROP TABLE IF EXISTS `$table`;\n".$create[1].";\n";$data=mysqli_query($conn,'SELECT * FROM `'.$table.'`');while($row=mysqli_fetch_assoc($data)){$values=[];foreach($row as $v)$values[]=$v===null?'NULL':"'".mysqli_real_escape_string($conn,$v)."'";$sql.="INSERT INTO `$table` (`".implode('`,`',array_keys($row))."`) VALUES(".implode(',',$values).");\n";}}$sql.="SET FOREIGN_KEY_CHECKS=1;\n";file_put_contents($path,$sql,LOCK_EX);$size=filesize($path);$actor=(int)$_SESSION['adminId'];$s=mysqli_prepare($conn,'INSERT INTO database_backups(file_name,file_path,file_size,created_by) VALUES(?,?,?,?)');mysqli_stmt_bind_param($s,'ssii',$name,$path,$size,$actor);mysqli_stmt_execute($s);oecrm_audit($conn,'backups','create','database_backup',mysqli_insert_id($conn),'Database backup created');header('Location: databaseMaintenance.php');
